    VALUES
        (335, 'customer-research', $zh240$客户研究与洞察$zh240$, $zh240$收集、分析并综合客户研究，覆盖访谈、问卷、工单、VOC、用户画像、JTBD、评论挖掘以及流失与转化原因。$zh240$, $zh240$用于开展、分析或综合客户研究，包括客户调研、ICP 研究、客户访谈、访谈问题、访谈记录、问卷、支持工单、VOC、用户画像、待办任务（JTBD）、Reddit 调研、评论挖掘、G2 评论、社群研究、论坛调研、客户情绪、客户为何流失、客户为何转化以及客户为何购买。既可分析现有研究资料，也可从网上收集新的客户洞察。文案调研请参见 copywriting，页面转化分析请参见 cro。$zh240$, 'coreyhaines31/marketingskills', 'customer-research', 0, FALSE),
        (336, 'amazon-product-research', $zh240$Amazon 选品与产品研究$zh240$, $zh240$面向 Amazon 卖家的系统化选品研究，评估需求、竞争、利润、进入壁垒，并形成采购、定价与上市建议。$zh240$, $zh240$为 Amazon 卖家执行全面的产品研究与机会验证。分析市场需求、竞争强度、盈利能力和进入壁垒，验证产品创意，并据此提出采购、定价及上市策略，帮助判断产品是否值得进入。$zh240$, 'nexscope-ai/amazon-skills', 'amazon-product-research', 0, FALSE),
        (337, 'figma', $zh240$Figma 到 HyperFrames 动效导入$zh240$, $zh240$把 Figma 设计导入 HyperFrames，重建设计资产、品牌 Token、组件和分镜，并转换为可编程动效状态。$zh240$, $zh240$将 Figma 设计导入 HyperFrames：提取渲染资产、品牌 Token、组件和分镜，把设计重建为可编程的运动帧状态。支持 REST 与 CLI 工作流，并可连接 HyperFrames 的运动和着色器能力。$zh240$, 'heygen-com/hyperframes', 'figma', 0, FALSE),
        (338, 'firecrawl-crawl', $zh240$Firecrawl 网站批量爬取$zh240$, $zh240$以可控深度、路径和并发批量爬取整个网站，适合整站内容提取与大规模页面采集。$zh240$, $zh240$使用 Firecrawl 对整个网站进行批量爬取和内容提取。适用于需要遍历多个页面、控制爬取深度与路径、调整并发度，或从整站系统收集内容的任务。$zh240$, 'firecrawl/cli', 'firecrawl-crawl', 0, TRUE),
        (339, 'firecrawl-agent', $zh240$Firecrawl 智能结构化提取$zh240$, $zh240$让 Firecrawl Agent 自主浏览复杂或多页网站，并按目标结构提取 JSON 数据。$zh240$, $zh240$使用 Firecrawl Agent 自主完成复杂、多步骤或跨页面的信息提取，并返回结构化 JSON。适用于仅凭普通抓取无法稳定定位内容、需要 Agent 自主探索网站或整合多个页面结果的任务。$zh240$, 'firecrawl/cli', 'firecrawl-agent', 0, TRUE),
        (340, 'firecrawl-map', $zh240$Firecrawl 站点 URL 地图$zh240$, $zh240$发现并列出网站 URL，支持搜索过滤和站点结构梳理，为后续抓取确定页面范围。$zh240$, $zh240$使用 Firecrawl 映射网站，发现并列出可访问的 URL。适用于搜索特定页面、按条件过滤 URL、理解站点结构，或在抓取前快速确定网站包含哪些页面。$zh240$, 'firecrawl/cli', 'firecrawl-map', 0, TRUE),
        (341, 'convex', $zh240$Convex 全栈后端开发$zh240$, $zh240$使用 Convex 构建类型安全的响应式后端，覆盖数据库、函数、实时数据、认证、存储、调度与可复用组件。$zh240$, $zh240$使用 Convex 构建完整的 TypeScript 响应式后端，包括数据库模式、查询、变更、动作、HTTP 函数、定时任务、文件存储、身份认证、实时订阅和类型安全事务。既适合快速原型，也适合扩展生产系统；还可使用组件实现 AI、RAG、工作流、速率限制、计费、搜索、邮件和在线状态等能力。凡涉及 Convex、后端或持久化需求时均应使用，并按任务需要转到 convex-* 专项目录。$zh240$, 'get-convex/agent-skills', 'convex', 0, TRUE),
        (342, 'firecrawl-download', $zh240$Firecrawl 网站离线下载$zh240$, $zh240$把网站内容以 Markdown、截图等多种格式下载到本地，并按站点结构组织文件。$zh240$, $zh240$使用 Firecrawl 将网站下载到本地，可保存 Markdown、截图及其他格式。该流程会先映射站点，再抓取页面，并把结果整理到结构清晰的目录中，适合离线阅读、归档或后续处理。$zh240$, 'firecrawl/cli', 'firecrawl-download', 0, TRUE),
        (343, 'theme-factory', $zh240$文档与页面主题工厂$zh240$, $zh240$为幻灯片、文档、报告和 HTML 页面应用预设或新生成的颜色与字体主题。$zh240$, $zh240$为幻灯片、文档、报告、HTML 页面等产物统一应用主题。可从 10 套预设主题中选择颜色和字体，也可根据内容与品牌需求生成新主题，从而保持整套产物的视觉一致性。$zh240$, 'anthropics/skills', 'theme-factory', 1, FALSE),
        (344, 'doc-coauthoring', $zh240$结构化文档协作$zh240$, $zh240$通过上下文传递、分轮迭代和读者验证，共同撰写提案、技术规范、决策文档等结构化内容。$zh240$, $zh240$以结构化工作流协助用户共同撰写文档、提案、技术规范、决策记录及类似内容。先高效传递背景和目标，再分轮完善结构与文字，最后从目标读者视角验证文档是否清楚、完整且能独立理解。$zh240$, 'anthropics/skills', 'doc-coauthoring', 0, TRUE),
        (345, 'computer-use', $zh240$Orca 桌面界面操作$zh240$, $zh240$通过 Orca CLI 读取无障碍树与截图，并安全操作桌面、浏览器和 WebView 界面。$zh240$, $zh240$使用 Orca 的 computer-use CLI 操作桌面应用、浏览器和 WebView。可读取无障碍树与屏幕截图，定位界面元素，并执行经过保护的点击、输入和导航等操作，适用于需要可靠控制本地图形界面的任务。$zh240$, 'stablyai/orca', 'computer-use', 0, FALSE),
        (346, 'wonda-cli', $zh240$Wonda 多媒体生成与社媒自动化$zh240$, $zh240$在终端生成图片、视频、音乐和音频，并自动执行 LinkedIn、Reddit 与 X 的研究和运营任务。$zh240$, $zh240$通过 Wonda CLI 在终端生成图片、视频、音乐和音频，还可自动执行 LinkedIn、Reddit 与 X 上的研究和操作。适合将多媒体创作与社交平台信息收集、内容处理或运营流程整合到命令行工作流中。$zh240$, 'degausai/wonda', 'wonda-cli', 0, TRUE),
        (347, 'firebase-remote-config-basics', $zh240$Firebase Remote Config 配置管理$zh240$, $zh240$管理 Remote Config 模板、功能开关、加载策略及 Android/iOS SDK 的获取与实时更新。$zh240$, $zh240$使用 Firebase Remote Config 管理模板、参数和功能开关，并在 Android 或 iOS 应用中实现加载策略。涵盖版本与默认值、fetchAndActivate、实时配置更新和常见 SDK 流程；不用于 Firebase Hosting、Authentication 等其他产品。$zh240$, 'firebase/agent-skills', 'firebase-remote-config-basics', 0, FALSE),
        (348, 'brand-guidelines', $zh240$Anthropic 品牌规范应用$zh240$, $zh240$把 Anthropic 官方颜色、字体与视觉风格应用到文档、页面和其他品牌化产物。$zh240$, $zh240$在需要遵循 Anthropic 品牌视觉时，使用其官方颜色、字体排版和整体风格规范处理文档、页面、演示或其他产物，使结果与 Anthropic 的既有品牌表达保持一致。$zh240$, 'anthropics/skills', 'brand-guidelines', 0, FALSE),
        (349, 'css-animations', $zh240$HyperFrames CSS 动画适配$zh240$, $zh240$把 CSS 动画接入 HyperFrames，控制关键帧、延迟、填充和播放状态，实现确定性逐帧定位。$zh240$, $zh240$为 HyperFrames 适配 CSS 动画。处理 @keyframes、animation-delay、animation-fill-mode 和 animation-play-state 等机制，使动画可被暂停、定位与逐帧复现，满足确定性渲染和时间轴跳转需求。$zh240$, 'heygen-com/hyperframes', 'css-animations', 0, FALSE),
        (350, 'algorithmic-art', $zh240$p5.js 算法艺术创作$zh240$, $zh240$使用 p5.js、固定随机种子和可调参数创作原创生成艺术与交互式视觉作品。$zh240$, $zh240$使用 p5.js 创作算法艺术和生成式视觉作品，通过固定随机种子保证可复现，并提供可交互的参数探索。作品应基于原创算法和审美构思，不模仿或复制在世艺术家的既有作品。$zh240$, 'anthropics/skills', 'algorithmic-art', 0, FALSE),
        (351, 'apple-design', $zh240$Apple 风格 Web 界面设计$zh240$, $zh240$把 Apple 的界面与动效理念转化为 Web 体验，覆盖手势、弹簧、拖拽、材质、层次和无障碍动效。$zh240$, $zh240$将 Apple 平台的界面和运动设计原则适配到 Web。涵盖手势、弹簧动画、拖拽与滑动、底部面板、惯性、动画中断、材质与景深、字体排版、减少动态效果偏好以及基础交互规范，用于打造自然、细腻且可访问的体验。$zh240$, 'emilkowalski/skills', 'apple-design', 0, FALSE),
        (352, 'obsidian-markdown', $zh240$Obsidian Markdown 编辑$zh240$, $zh240$创建和编辑 Obsidian 风格 Markdown，支持双链、嵌入、Callout、属性、Frontmatter 与标签。$zh240$, $zh240$创建或修改兼容 Obsidian 的 Markdown 文档。正确使用双向链接、内容嵌入、Callout、属性、YAML Frontmatter、标签及其他 Obsidian 扩展语法，适合维护知识库中的笔记与关联结构。$zh240$, 'kepano/obsidian-skills', 'obsidian-markdown', 0, FALSE),
        (353, 'tailwind', $zh240$HyperFrames Tailwind CSS 适配$zh240$, $zh240$在 HyperFrames 浏览器运行时接入 Tailwind CSS v4.2，配置实用类、CSS-first Token 并排查版本问题。$zh240$, $zh240$在 HyperFrames 中使用 Tailwind CSS v4.2 浏览器运行时。涵盖通过 --tailwind 初始化、使用实用类、采用 CSS-first 方式定义设计 Token、排查 v3 与 v4 差异，以及判断何时应改用预编译方案。$zh240$, 'heygen-com/hyperframes', 'tailwind', 0, FALSE),
        (354, 'animejs', $zh240$HyperFrames Anime.js 动画适配$zh240$, $zh240$把 Anime.js 时间轴接入 HyperFrames，通过统一注册与 seek 实现可复现、渲染安全的 HTML 动画。$zh240$, $zh240$为 HyperFrames 适配 Anime.js 动画。构建 Anime.js 时间轴，通过 window.__hfAnime 统一注册，并提供可精确 seek 的确定性控制，使 HTML 动画能够安全地逐帧渲染和复现。$zh240$, 'heygen-com/hyperframes', 'animejs', 0, FALSE),
        (355, 'stripe-best-practices', $zh240$Stripe 集成最佳实践$zh240$, $zh240$按 Stripe 官方最佳实践选择 API 并实现支付、订阅、税务、Connect、密钥、Webhook 与迁移。$zh240$, $zh240$为 Stripe 集成提供官方最佳实践，包括 API 选择、Connect Accounts v2、Billing 与订阅、Stripe Tax、Treasury、Checkout、Payment Element、版本迁移、密钥管理、Webhook 和 OAuth。适用于设计、实现或审查 Stripe 支付及平台型业务集成。$zh240$, 'stripe/ai', 'stripe-best-practices', 0, FALSE),
        (356, 'three', $zh240$HyperFrames Three.js 与 WebGL 适配$zh240$, $zh240$构建可确定性渲染的 Three.js/WebGL 场景，控制画布、相机、AnimationMixer、着色器与时间定位。$zh240$, $zh240$为 HyperFrames 适配 Three.js 与 WebGL。构建确定性的三维场景和画布，管理相机、AnimationMixer、材质与着色器，并接入 hf-seek 时间定位，使每一帧均可稳定复现和导出。$zh240$, 'heygen-com/hyperframes', 'three', 0, FALSE),
        (357, 'playwright-best-practices', $zh240$Playwright 测试最佳实践$zh240$, $zh240$系统指导 Playwright 的端到端、组件、API、视觉、无障碍和安全测试，并解决稳定性、调试与 CI 问题。$zh240$, $zh240$为 Playwright 测试提供系统化最佳实践，覆盖端到端、组件、API、视觉回归、无障碍、安全、Electron 和浏览器扩展测试。用于治理不稳定测试、调试失败、设计 Page Object、优化 CI 与性能，处理 Mock、认证与 OAuth、axe、文件上传、日期时间、WebSocket、地理位置、权限、多标签页、移动端与触控、GraphQL、离线、协作场景、控制台错误、全局配置、注解与标签、安全预算、iframe、Canvas、PWA、覆盖率和国际化等测试需求。$zh240$, 'currents-dev/playwright-best-practices-skill', 'playwright-best-practices', 0, FALSE),
        (358, 'lottie', $zh240$HyperFrames Lottie 动画适配$zh240$, $zh240$在 HyperFrames 中加载 Lottie JSON 或 .lottie 文件，并实现 After Effects 动画的确定性时间控制。$zh240$, $zh240$为 HyperFrames 适配 Lottie 与 dotLottie 动画。支持通过 lottie-web 加载 JSON、通过 dotlottie-web 加载 .lottie 文件，并在 window.__hfLottie 中注册实例，使来自 After Effects 的动画可被确定性定位和逐帧渲染。$zh240$, 'heygen-com/hyperframes', 'lottie', 0, FALSE),
        (359, 'waapi', $zh240$HyperFrames Web Animations API 适配$zh240$, $zh240$把 Web Animations API 接入 HyperFrames，以 currentTime 和 KeyframeEffect 精确控制并复现动画。$zh240$, $zh240$为 HyperFrames 适配 Web Animations API。使用 element.animate、currentTime、document.getAnimations、KeyframeEffect 和填充模式来构建、暂停与定位动画，确保渲染过程具有确定性。$zh240$, 'heygen-com/hyperframes', 'waapi', 0, FALSE),
        (360, 'gws-gmail', $zh240$Gmail 邮件管理$zh240$, $zh240$通过 Google Workspace CLI 发送、读取和管理 Gmail 邮件。$zh240$, $zh240$使用 Google Workspace CLI 操作 Gmail，包括发送和读取邮件，以及管理邮箱中的相关资源与流程。$zh240$, 'googleworkspace/cli', 'gws-gmail', 0, FALSE),
        (361, 'audit-website', $zh240$网站全维度审计与修复$zh240$, $zh240$使用 SquirrelScan 按 260 多项规则审计网站的 SEO、性能、安全、内容、技术与无障碍问题并迭代修复。$zh240$, $zh240$使用 SquirrelScan 对网站执行全面审计，覆盖 15 个类别、260 多条规则，包括 SEO、性能、安全、技术、内容和无障碍。生成可操作报告，将问题映射到代码，按优先级修复后重新审计，持续迭代直至关键问题得到解决。$zh240$, 'squirrelscan/skills', 'audit-website', 1, FALSE),
        (362, 'social-content', $zh240$社交媒体内容策划$zh240$, $zh240$为 LinkedIn、X、Instagram、TikTok 和 Facebook 创建、排期与优化内容，并进行复用和互动提升。$zh240$, $zh240$创建、安排和优化社交媒体内容，覆盖 LinkedIn、X、Instagram、TikTok 与 Facebook。用于制定内容日历、提升互动、探索高传播潜力主题、内容再利用、轮播帖设计和短视频脚本。整体内容战略请参见 content-strategy，付费投放请参见 paid-ads。$zh240$, 'coreyhaines31/marketingskills', 'social-content', 0, FALSE),
