        (364, 'typeset', $zh240$排版与字体精修$zh240$, $zh240$优化字体选择、层级、字号、字重和可读性，建立清晰一致的界面排版。$zh240$, $zh240$审视并改进界面排版，包括字体选择、视觉层级、字号、字重、行距与整体可读性，使信息结构清晰、风格一致，并适应不同内容和屏幕尺寸。$zh240$, 'pbakaus/impeccable', 'typeset', 0, FALSE),
        (365, 'improve-animations', $zh240$动效系统审计与改进计划$zh240$, $zh240$以资深动效设计视角只读审计代码库，给出按优先级排序的具体问题与实现方案，不直接改动代码。$zh240$, $zh240$以资深运动设计师的视角对代码库进行只读审计，评估现有动画的节奏、缓动、反馈、一致性、性能和无障碍。输出按优先级排序的审计结果及可执行的实现计划，但不直接应用修改。$zh240$, 'emilkowalski/skills', 'improve-animations', 0, FALSE),
        (366, 'internal-comms', $zh240$企业内部沟通写作$zh240$, $zh240$按组织惯用格式撰写状态更新、领导汇报、3P、新闻简报、FAQ、事故与项目沟通。$zh240$, $zh240$协助撰写各类企业内部沟通材料，并采用组织偏好的格式。覆盖项目状态更新、领导层汇报、3P 更新、公司新闻简报、FAQ、事故说明和项目沟通等常见场景。$zh240$, 'anthropics/skills', 'internal-comms', 0, FALSE),
        (367, 'notion-api', $zh240$Notion API 全面操作$zh240$, $zh240$通过 Notion REST API 读取、创建、更新和删除页面、数据库、区块与评论。$zh240$, $zh240$使用 Notion REST API 对页面、数据库、区块和评论执行读取、创建、更新与删除操作。涵盖身份认证、端点选择、分页、错误处理及常见最佳实践，适用于构建完整的 Notion 自动化与集成。$zh240$, 'intellectronica/agent-skills', 'notion-api', 0, FALSE),
        (368, 'overdrive', $zh240$界面极致视觉强化$zh240$, $zh240$以着色器、弹簧和滚动揭示等高表现力技术强化界面，同时维持流畅的 60 FPS 体验。$zh240$, $zh240$把界面视觉表现推向更大胆、更令人惊艳的方向，可运用着色器、弹簧动画、滚动揭示等高级效果创造记忆点，同时严格控制性能，确保交互保持流畅并力争稳定达到 60 FPS。$zh240$, 'pbakaus/impeccable', 'overdrive', 0, FALSE),
        (369, 'gws-drive', $zh240$Google Drive 文件管理$zh240$, $zh240$通过 Google Workspace CLI 管理 Google Drive 的文件、文件夹与共享云端硬盘。$zh240$, $zh240$使用 Google Workspace CLI 操作 Google Drive，包括查找、读取和管理文件、文件夹及共享云端硬盘中的资源。$zh240$, 'googleworkspace/cli', 'gws-drive', 0, FALSE),
        (370, 'batch-grill-me', $zh240$批量深度追问$zh240$, $zh240$一次提出所有关键前沿问题，并逐轮持续追问，直到模糊点和决策依据全部澄清。$zh240$, $zh240$对一个主题进行高强度批量追问：每一轮一次性提出所有关键且接近认知边界的问题，再根据回答继续下一轮，不轻易放过含糊、矛盾或缺乏依据之处，直至问题得到充分澄清。$zh240$, 'mattpocock/skills', 'batch-grill-me', 0, FALSE),
        (371, 'developing-genkit-js', $zh240$Genkit JavaScript/TypeScript 开发$zh240$, $zh240$使用 Genkit 的 Node.js 与 TypeScript SDK 构建 AI 应用、Agent、Flow 和工具。$zh240$, $zh240$使用 Genkit 的 JavaScript/TypeScript SDK 开发 AI 应用和 Agent。涵盖 Flow、工具、模型调用、结构化输入输出、错误处理、类型与 API 设计，适用于 Node.js 和 TypeScript 项目。$zh240$, 'firebase/agent-skills', 'developing-genkit-js', 0, FALSE),
        (372, 'developing-genkit-dart', $zh240$Genkit Dart 与 Flutter 开发$zh240$, $zh240$使用 Genkit Dart SDK 在 Dart 和 Flutter 中构建 AI Agent、Flow 与大模型功能。$zh240$, $zh240$使用 Genkit Dart SDK 开发 AI 应用，包括 Agent、Flow、大语言模型调用和相关工具，适用于 Dart 后端及 Flutter 应用中的生成式 AI 功能。$zh240$, 'firebase/agent-skills', 'developing-genkit-dart', 0, FALSE),
        (373, 'obsidian-cli', $zh240$Obsidian 命令行与插件开发$zh240$, $zh240$通过 Obsidian CLI 管理仓库、笔记、任务和属性，并辅助插件或主题的开发调试。$zh240$, $zh240$使用 Obsidian CLI 操作知识库、笔记、任务和属性。还支持插件与主题开发流程，包括重新加载、执行 JavaScript、查看错误、截图和检查 DOM，适合自动化内容管理与扩展调试。$zh240$, 'kepano/obsidian-skills', 'obsidian-cli', 0, FALSE),
        (374, 'cross-border-ecommerce', $zh240$跨境电商市场扩张$zh240$, $zh240$从八个维度评估目标市场，比较五种履约模式，并分析主要地区税费、支付偏好与分阶段进入路线。$zh240$, $zh240$为跨境电商制定市场扩张方案：从八个维度为候选市场评分，比较五种履约模式，分析欧盟、英国、美国、加拿大、澳大利亚和日本的税费与关税要求，结合当地支付偏好，形成分阶段的市场进入路线图。$zh240$, 'nexscope-ai/ecommerce-skills', 'cross-border-ecommerce', 0, FALSE),
        (375, 'pricing-strategy', $zh240$产品定价与商业化策略$zh240$, $zh240$设计价格、套餐和商业化模式，覆盖分层、免费增值、试用、涨价、价值指标与支付意愿研究。$zh240$, $zh240$用于产品定价决策、套餐设计和商业化策略。涵盖价格层级、免费增值、免费试用、套餐组合、涨价、价值指标、Van Westendorp 与支付意愿研究，以及按席位、月付或年付等结构选择。应用内升级界面请参见 paywall。$zh240$, 'coreyhaines31/marketingskills', 'pricing-strategy', 0, FALSE),
        (376, 'product-marketing-context', $zh240$产品营销上下文文档$zh240$, $zh240$创建或更新可复用的产品营销上下文，集中记录产品、受众、定位与市场信息，供后续营销任务引用。$zh240$, $zh240$创建或更新 .agents/product-marketing-context.md，把产品、目标客户、定位、价值主张、竞争环境和营销背景整理成可复用的上下文。适合在新项目开始时建立统一事实基础，也可在信息变化后维护该文档，减少后续营销任务中的重复说明。$zh240$, 'coreyhaines31/marketingskills', 'product-marketing-context', 0, FALSE),
        (377, 'slack-gif-creator', $zh240$Slack 动图制作$zh240$, $zh240$按照 Slack 的尺寸与文件限制设计、生成并验证循环流畅、表达清晰的动画 GIF。$zh240$, $zh240$创建适合 Slack 使用的动画 GIF。根据平台约束选择画布、帧率、时长和压缩方式，帮助构思动画内容并验证最终文件的尺寸、体积、循环和可读性，确保在 Slack 中正常显示。$zh240$, 'anthropics/skills', 'slack-gif-creator', 0, FALSE),
        (378, 'firecrawl-interact', $zh240$Firecrawl 浏览器交互自动化$zh240$, $zh240$在实时浏览器会话中点击、填写、导航和提取数据，处理认证、分页、无限滚动及多步骤流程。$zh240$, $zh240$通过 Firecrawl 的实时浏览器会话与网页交互，可用自然语言或代码执行点击、表单填写、导航和数据提取。适用于需要登录状态、保存浏览器配置、运行 JavaScript、处理分页或无限滚动，以及完成多步骤网页流程的任务。$zh240$, 'firecrawl/cli', 'firecrawl-interact', 0, TRUE),
        (379, 'obsidian-bases', $zh240$Obsidian Bases 数据视图$zh240$, $zh240$创建和编辑 Obsidian .base 文件，配置视图、过滤器、公式与汇总，并生成表格或卡片展示。$zh240$, $zh240$创建或修改 Obsidian Bases 的 .base 文件。支持定义数据源、视图、过滤条件、公式和汇总规则，并将笔记数据组织成表格、卡片等可浏览视图。$zh240$, 'kepano/obsidian-skills', 'obsidian-bases', 0, FALSE),
        (380, 'turborepo', $zh240$Turborepo 单体仓库构建$zh240$, $zh240$配置和优化 Turborepo 的任务管线、缓存、筛选、受影响范围、CI、环境变量及包边界。$zh240$, $zh240$构建和维护 Turborepo 单体仓库。涵盖 turbo.json 任务管线、dependsOn 依赖关系、缓存、filter 与 affected 范围、CI 优化、环境变量、内部包和工作区边界。凡涉及 turbo 命令、任务缓存、单体仓库结构或跨包构建问题时均适用。$zh240$, 'vercel/turborepo', 'turborepo', 0, FALSE),
        (381, 'typescript-advanced-types', $zh240$TypeScript 高级类型系统$zh240$, $zh240$运用泛型、条件类型、映射类型、模板字面量和工具类型构建严谨、可复用的类型安全 API。$zh240$, $zh240$掌握并应用 TypeScript 高级类型，包括泛型、条件类型、映射类型、模板字面量类型和各类工具类型。适用于设计复杂但可维护的类型关系、创建可复用的类型工具，并在编译期保证 API 与业务逻辑的类型安全。$zh240$, 'wshobson/agents', 'typescript-advanced-types', 0, FALSE),
        (382, 'building-native-ui', $zh240$Expo 原生质感界面构建$zh240$, $zh240$依据 Apple HIG 和平台惯例构建具有原生质感的 Expo 界面，兼顾控件、动效、媒体、材质与响应式布局。$zh240$, $zh240$使用 Expo 构建具有原生平台质感的界面。遵循 Apple HIG，采用语义颜色、原生控件、SF Symbols、媒体组件、动画、视觉效果、渐变和本地存储，并处理不同设备上的响应式布局。路由相关任务请使用专门的路由能力。$zh240$, 'expo/skills', 'building-native-ui', 0, FALSE),
        (383, 'tailwind-design-system', $zh240$Tailwind CSS 设计系统构建$zh240$, $zh240$使用 Tailwind CSS v4 建立可扩展的设计 Token、组件模式和响应式规范。$zh240$, $zh240$基于 Tailwind CSS v4 构建可扩展的设计系统。定义一致的设计 Token、可复用组件、状态和变体，并制定响应式模式，使产品界面能够高效扩展且保持视觉一致。$zh240$, 'wshobson/agents', 'tailwind-design-system', 0, FALSE),
        (384, 'template-skill', $zh240$Skill 模板占位示例$zh240$, $zh240$用于新建 Skill 时填写能力边界与触发条件的占位模板。$zh240$, $zh240$请在此替换为该 Skill 的能力说明，以及 Claude 应在什么情况下使用它。$zh240$, 'anthropics/skills', 'template-skill', 0, TRUE),
        (385, 'competitor-profiling', $zh240$竞争对手深度画像$zh240$, $zh240$从竞争对手网址及公开资料构建结构化档案，用于竞争分析、情报、审计和市场判断。$zh240$, $zh240$根据竞争对手网址及其他公开资料创建结构化竞争档案。用于竞争分析、竞争情报、对手资料册、市场审计或深度拆解，系统整理其产品、定位、受众、信息表达、定价、渠道、优势和弱点。对比页面请参见 competitor-alternatives，销售资料请参见 sales-enablement。$zh240$, 'coreyhaines31/marketingskills', 'competitor-profiling', 0, FALSE),
        (386, 'design-md', $zh240$Stitch 设计系统提炼$zh240$, $zh240$分析 Stitch 项目并把颜色、字体、间距、组件和视觉规律综合为语义化 DESIGN.md。$zh240$, $zh240$分析现有 Stitch 项目，从页面和组件中提炼颜色、字体、间距、形状、层级与交互模式，并将其综合成语义清晰、可复用的设计系统文档 DESIGN.md，供后续页面和组件保持一致。$zh240$, 'google-labs-code/stitch-skills', 'design-md', 0, FALSE),
        (387, 'analytics-tracking', $zh240$分析埋点与转化衡量$zh240$, $zh240$搭建、改进或审计 GA4、GTM、事件、UTM、转化及 Mixpanel、Segment 等分析体系。$zh240$, $zh240$用于设置、改进或审计分析跟踪与衡量体系。覆盖 GA4、Google Analytics、转化跟踪、事件设计、UTM 参数、Tag Manager、GTM、埋点计划、Mixpanel、Segment，以及排查事件是否触发和数据为何异常。归因模型选择请参见 attribution，A/B 测试衡量请参见 ab-testing。$zh240$, 'coreyhaines31/marketingskills', 'analytics-tracking', 0, FALSE),
        (388, 'is-this-photo-real', $zh240$图像与视频真实性核验$zh240$, $zh240$通过取证方法、元数据与来源线索评估媒体真伪，并解释 AI 检测器和单项证据的局限。$zh240$, $zh240$评估照片或视频是否真实、经过编辑或由 AI 生成。综合使用来源与元数据、误差级别分析、噪声与 JPEG 痕迹、克隆和复制移动检测、光影一致性、C2PA 凭证及深度伪造线索，并明确 AI 检测器的局限。适用于 KYC、保险、虚假信息调查和证据核验等场景。$zh240$, 'useosint/osint-skills', 'is-this-photo-real', 0, FALSE),
        (389, 'page-cro', $zh240$营销页面转化率优化$zh240$, $zh240$诊断并优化首页、落地页、定价页、功能页和博客等营销页面的转化表现。$zh240$, $zh240$分析和改进任何营销页面的转化率，包括首页、落地页、定价页、功能页和博客文章。找出信息层级、文案、信任、阻力、CTA 与页面结构中的问题，并提出优先级明确的改进。注册、引导、表单和弹窗流程请使用相应的专项能力。$zh240$, 'coreyhaines31/marketingskills', 'page-cro', 0, FALSE),
        (390, 'investigate-without-getting-made', $zh240$隐蔽调查与身份防护$zh240$, $zh240$规划调查操作安全，减少 IP、浏览器、TLS、时间行为和账号关联带来的身份暴露。$zh240$, $zh240$为合法调查规划操作安全与归因防护，评估 IP 与 ASN、浏览器指纹、TLS 特征、时间规律和账号关联等暴露面。指导身份隔离、调查专用账号，以及 VPN、代理或 Tor 的合理选择，适用于尽职调查、新闻调查、执法与其他获授权的研究；应遵守法律、平台规则和组织政策。$zh240$, 'useosint/osint-skills', 'investigate-without-getting-made', 0, FALSE),
        (391, 'solana-dev', $zh240$Solana 全栈开发$zh240$, $zh240$端到端开发、测试、调试和部署 Solana dApp、Anchor 程序与 Token，并集成钱包和现代 SDK。$zh240$, $zh240$完成 Solana 应用的端到端开发，包括链上程序、Anchor、Token、钱包连接、测试、调试和部署，并解释相关核心概念。支持 RPC 查询、Kit v7、钱包插件与 React、web3.js v3，以及 Surfpool、LiteSVM 和 Mollusk 等本地测试工具。$zh240$, 'solana-foundation/solana-dev-skill', 'solana-dev', 0, FALSE),
        (392, 'firecrawl-build-scrape', $zh240$Firecrawl 单页抓取集成$zh240$, $zh240$在应用中集成 Firecrawl /scrape，提取单页的 Markdown、HTML、链接、截图、元数据与结构化内容。$zh240$, $zh240$把 Firecrawl 的 /scrape 端点集成到应用中，用于从已知 URL 提取单个页面。可返回 Markdown、HTML、链接、截图、元数据或按模式生成的结构化内容；适合页面级采集，而非整站爬取。$zh240$, 'firecrawl/skills', 'firecrawl-build-scrape', 0, FALSE),
        (393, 'upgrade-stripe', $zh240$Stripe API 与 SDK 升级$zh240$, $zh240$安全升级 Stripe API 版本和 SDK，识别破坏性变化并完成迁移验证。$zh240$, $zh240$协助将 Stripe 集成升级到新的 API 版本或 SDK 版本。检查版本差异与破坏性变更，更新代码和配置，处理弃用项，并验证支付、Webhook 及其他关键流程在迁移后仍能正确工作。$zh240$, 'stripe/ai', 'upgrade-stripe', 0, FALSE),
        (394, 'firecrawl-build-search', $zh240$Firecrawl 网页搜索集成$zh240$, $zh240$在应用中集成 Firecrawl /search，先按查询发现网页，再按需抓取并补全结果内容。$zh240$, $zh240$把 Firecrawl 的 /search 端点集成到应用中。当只有搜索主题而没有确定 URL 时，先发现相关网页，再选择是否抓取并补全页面内容。适用于搜索驱动的信息发现与提取工作流。$zh240$, 'firecrawl/skills', 'firecrawl-build-search', 0, FALSE),
        (395, 'what-leaked-about-you', $zh240$个人数据泄露暴露检查$zh240$, $zh240$查询邮箱、用户名、电话或姓名在数据泄露中的暴露情况，并给出账户与隐私风险处置建议。$zh240$, $zh240$检查个人邮箱、用户名、电话号码或姓名是否出现在已知数据泄露中。可使用 Have I Been Pwned、Pwned Passwords 的 k-匿名查询及获授权的 DeHashed、Intelligence X、Snusbase 等服务，适用于事件响应、账号接管风险、重要人员筛查和个人隐私评估；不得滥用泄露数据。$zh240$, 'useosint/osint-skills', 'what-leaked-about-you', 0, FALSE),
        (396, 'firecrawl-build-interact', $zh240$Firecrawl 动态交互集成$zh240$, $zh240$在应用中集成 Firecrawl /interact，通过点击、表单、分页和认证处理动态网页与多步骤流程。$zh240$, $zh240$把 Firecrawl 的 /interact 能力集成到应用中，用于无法仅靠静态抓取完成的动态网页流程。支持点击元素、填写表单、处理分页、使用认证状态并串联多步骤操作，最终提取所需结果。$zh240$, 'firecrawl/skills', 'firecrawl-build-interact', 0, FALSE),
        (397, 'firecrawl-build-onboarding', $zh240$Firecrawl 接入与认证配置$zh240$, $zh240$完成 Firecrawl 凭证、SDK、环境变量和浏览器认证配置，为后续抓取与交互集成建立基础。$zh240$, $zh240$完成 Firecrawl 的初始接入：获取并配置凭证、安装 SDK、在 .env 中设置 FIRECRAWL_API_KEY，并在需要时建立浏览器认证状态。适合首次使用或排查认证与环境配置问题。$zh240$, 'firecrawl/skills', 'firecrawl-build-onboarding', 0, FALSE),
        (398, 'claude-api', $zh240$Claude API 与 Anthropic SDK 参考$zh240$, $zh240$提供 Claude API、Anthropic SDK、模型、流式响应、工具调用、MCP、缓存、Token 与迁移的完整参考。$zh240$, $zh240$回答 Claude API 和 Anthropic SDK 相关问题，并协助构建集成。覆盖模型与价格、请求参数、流式响应、工具调用、MCP、Agent、提示缓存、Token 计算和迁移。用户提到 Claude、Anthropic 或未明确厂商但呈现大模型 API 形态的代码时使用；若明确采用其他厂商，或代码库检索确认不是 Anthropic 集成，则不应使用。$zh240$, 'anthropics/skills', 'claude-api', 0, FALSE),
        (399, 'json-canvas', $zh240$Obsidian JSON Canvas 编辑$zh240$, $zh240$创建和编辑 .canvas 文件中的节点、边、分组与连接，用于思维导图、流程图和可视化知识画布。$zh240$, $zh240$创建或修改 Obsidian JSON Canvas 的 .canvas 文件。支持文本、文件和链接节点，节点之间的边与连接，以及分组和布局，适用于构建思维导图、流程图和其他可视化知识结构。$zh240$, 'kepano/obsidian-skills', 'json-canvas', 0, FALSE),
        (400, 'community-marketing', $zh240$社群营销与用户增长$zh240$, $zh240$规划、建立并运营 Discord、Slack、论坛或 Subreddit 社群，推动口碑、倡导者和社群驱动增长。$zh240$, $zh240$制定线上社群营销战略，覆盖 Discord、Slack、论坛、Subreddit 及其他用户社区。用于启动和运营社群、培养用户倡导者、促进成员互动与口碑传播，并把社群活动连接到留存和社群驱动增长目标。$zh240$, 'coreyhaines31/marketingskills', 'community-marketing', 0, FALSE),
        (401, 'launch-strategy', $zh240$产品发布与上市策略$zh240$, $zh240$规划产品或功能发布，覆盖上市路径、Product Hunt、Beta、抢先体验、候补名单和发布清单。$zh240$, $zh240$为产品、功能或重要版本制定发布与上市策略。适用于 Product Hunt、功能公告、GTM、Beta 发布、抢先体验、候补名单和产品更新，形成受众、信息、渠道、节奏、资产与发布后跟进都清晰的执行清单。$zh240$, 'coreyhaines31/marketingskills', 'launch-strategy', 0, FALSE),
        (402, 'contribute-catalog', $zh240$HyperFrames 公共组件目录贡献$zh240$, $zh240$为 HyperFrames 公共目录开发可注册的 Block 或组件，并按要求提交贡献 PR。$zh240$, $zh240$为 HyperFrames 公共目录编写新的注册项、Block 或组件，并准备符合规范的贡献 PR。该能力用于向公共目录贡献内容，不用于当前项目内直接创建普通组件，也不负责安装已有目录项。$zh240$, 'heygen-com/hyperframes', 'contribute-catalog', 0, FALSE),
        (403, 'find-the-original-image', $zh240$图片来源反向追踪$zh240$, $zh240$通过多引擎反向搜图和视频关键帧追踪图片最早出处、原作者、素材来源与传播链。$zh240$, $zh240$使用 Yandex、Google Lens、Bing、TinEye、百度等反向图像搜索服务查找图片原始来源。可识别最早发布、原作者、图库素材、转载链和更高质量版本，也可从视频抽取关键帧追踪来源，适用于欺诈、虚假信息、品牌和保险调查。$zh240$, 'useosint/osint-skills', 'find-the-original-image', 0, FALSE),
        (404, 'schema-markup', $zh240$Schema 结构化数据优化$zh240$, $zh240$添加、修复和优化 JSON-LD 与 schema.org 标记，提升搜索富媒体结果和页面语义。$zh240$, $zh240$为网站添加、修复或优化 Schema 标记与结构化数据。涵盖 JSON-LD、schema.org、FAQ、产品、评论、面包屑等类型，以及 Google 富媒体结果、知识面板和星级展示。更广泛的 SEO 问题请参见 seo-audit，AI 搜索优化请参见 ai-seo。$zh240$, 'coreyhaines31/marketingskills', 'schema-markup', 0, FALSE),
        (405, 'defuddle', $zh240$Defuddle 网页正文提取$zh240$, $zh240$通过 Defuddle CLI 移除网页杂乱元素并提取干净 Markdown，适合读取普通网页正文。$zh240$, $zh240$使用 Defuddle CLI 从网页中提取干净、可读的 Markdown，自动移除导航、广告及其他杂乱元素。读取普通网页内容时优先于 WebFetch；目标本身是 .md 文件时无需使用。$zh240$, 'kepano/obsidian-skills', 'defuddle', 0, FALSE),
        (406, 'email-sequence', $zh240$自动化邮件序列设计$zh240$, $zh240$创建和优化滴灌、培育、欢迎、引导、召回与生命周期邮件等多封自动化流程。$zh240$, $zh240$设计或优化多封邮件组成的自动化序列，包括滴灌、培育、用户引导、欢迎、召回、生命周期和基于触发条件的邮件流程。适用于规划邮件节奏、内容和分支。冷邮件请参见 cold-email，应用内引导请参见 onboarding。$zh240$, 'coreyhaines31/marketingskills', 'email-sequence', 0, FALSE),
        (407, 'image', $zh240$营销图像生成与优化$zh240$, $zh240$使用多种模型和工具创建、编辑与优化营销图像，并根据用途选择格式、尺寸和处理流程。$zh240$, $zh240$为营销场景创建、编辑和优化图像，按目标在多种生成模型与工具之间选择，并处理构图、风格、文字、尺寸、格式和压缩。付费广告素材请参见 ad-creative，视频任务请参见 video。$zh240$, 'coreyhaines31/marketingskills', 'image', 0, FALSE),
        (408, 'video', $zh240$AI 视频制作与生产$zh240$, $zh240$使用 AI 与程序化工具完成视频创意、生成、编辑、风格复现和生产流程。$zh240$, $zh240$使用 AI 模型和程序化工具创建与制作视频，覆盖概念设计、生成、剪辑、风格分析与复现、素材组合及交付流程。整体内容战略请使用相应营销能力，付费广告视频素材请参见 ad-creative。$zh240$, 'coreyhaines31/marketingskills', 'video', 0, FALSE),
        (409, 'normalize', $zh240$UI 设计系统归一化$zh240$, $zh240$审计并重新对齐界面的间距、Token、组件和交互模式，使其回归统一设计系统。$zh240$, $zh240$检查界面中偏离设计系统的部分，并重新对齐间距、颜色、字体、圆角、阴影、组件变体和交互模式。减少不一致与一次性样式，使页面重新遵循共享 Token 和可复用规范。$zh240$, 'pbakaus/impeccable', 'normalize', 0, FALSE),
        (410, 'gws-shared', $zh240$Google Workspace CLI 通用规范$zh240$, $zh240$提供 Google Workspace CLI 的共享认证、全局参数、输出格式和通用操作约定。$zh240$, $zh240$说明 Google Workspace CLI 各服务共同使用的基础能力，包括身份认证、全局命令行参数、输出格式、错误处理和通用约定，为 Gmail、Drive、Calendar、Sheets、Docs 等专用操作提供统一基础。$zh240$, 'googleworkspace/cli', 'gws-shared', 0, FALSE),
        (411, 'paid-ads', $zh240$付费广告投放优化$zh240$, $zh240$规划和优化 Google、Meta、LinkedIn 与 X 等平台的 PPC 广告，改善受众、竞价、预算、CPA 和 ROAS。$zh240$, $zh240$为 Google Ads、Meta、LinkedIn、X 等平台制定和优化付费广告活动。覆盖 PPC、受众定位、再营销、竞价、预算、关键词、CPA、ROAS 和效果评估。批量广告创意请参见 ad-creative，落地页优化请参见 cro。$zh240$, 'coreyhaines31/marketingskills', 'paid-ads', 0, FALSE),
        (412, 'developing-genkit-js-genkit-ai-skills', $zh240$Genkit JavaScript 开发（genkit-ai）$zh240$, $zh240$使用 genkit-ai 来源的 JavaScript/TypeScript 指南构建 Genkit AI 应用、Agent、Flow 与工具。$zh240$, $zh240$使用 Genkit 的 JavaScript/TypeScript SDK 开发 AI 应用和 Agent。涵盖 Flow、工具、模型调用、结构化输入输出、错误处理、类型与 API 设计，适用于 Node.js 和 TypeScript 项目；本条目对应 genkit-ai/skills 来源的实现指南。$zh240$, 'genkit-ai/skills', 'developing-genkit-js', 0, TRUE),
        (413, 'stripe-projects', $zh240$Stripe Projects 云服务预配$zh240$, $zh240$通过 Stripe Projects 直接预配数据库、认证、缓存、托管、向量服务和 API 密钥等项目基础设施。$zh240$, $zh240$使用 Stripe Projects 为项目预配和管理外部服务与基础设施，包括 PostgreSQL、Redis、认证、缓存、托管、向量数据库、API 密钥和监控。可浏览服务目录、查看项目状态并配置环境变量；应通过该流程创建资源，而不是要求用户手动注册各服务。$zh240$, 'stripe/ai', 'stripe-projects', 0, FALSE),
        (414, 'directory-submissions', $zh240$产品目录提交与外链增长$zh240$, $zh240$把产品提交到 Product Hunt、G2 等目录并维护进度，以提升发现度、引用与高质量外链。$zh240$, $zh240$规划并执行产品目录提交，将产品发布到 Product Hunt、G2 和其他相关目录，维护提交清单与进度，提升产品发现度、引用和外链。发布活动请参见 launch，程序化目录页请参见 programmatic-seo，面向 AI 引用的工作请参见 ai-seo。$zh240$, 'coreyhaines31/marketingskills', 'directory-submissions', 0, FALSE),
        (415, 'cloudflare', $zh240$Cloudflare 平台开发$zh240$, $zh240$面向 Cloudflare 全平台开发与运维，覆盖 Workers、Pages、存储、AI、网络、安全和基础设施即代码。$zh240$, $zh240$开发和维护 Cloudflare 平台上的应用与基础设施，覆盖 Workers、Pages、KV、D1、R2、Workers AI、Vectorize、Agents、工作流、Tunnel、Spectrum、WAF、DDoS 防护，以及 Terraform 与 Pulumi。处理 Cloudflare 任务时优先检索当前官方文档，再据此设计、实现和排障。$zh240$, 'cloudflare/skills', 'cloudflare', 221, FALSE),
        (416, 'competitor-alternatives', $zh240$竞品对比与替代方案页面$zh240$, $zh240$为 SEO 与销售支持创建可信的竞品对比和替代方案页面，覆盖四种常见内容结构。$zh240$, $zh240$创建用于 SEO 和销售支持的竞争对手对比或替代方案页面。支持四种格式：单一替代方案、多个替代方案、本产品与竞品对比、竞品之间对比。强调深入研究、可复用的模块化结构和可信论证，而非简单功能表。销售专用竞品资料请参见 sales-enablement。$zh240$, 'coreyhaines31/marketingskills', 'competitor-alternatives', 0, FALSE),
        (417, 'nia', $zh240$Nia AI 知识索引与检索$zh240$, $zh240$使用 Nia 索引并检索代码仓库、文档、论文、数据集和协作工具内容，支持研究、追踪与上下文问答。$zh240$, $zh240$使用 Nia AI 索引、搜索和研究多种知识来源，包括代码仓库、文档、论文、Hugging Face、本地文件、Slack、Google Drive、X 和软件包。涵盖认证、Oracle 深度研究、GitHub 实时信息、Tracer、依赖分析、上下文顾问、文档与数据处理以及连接器配置。$zh240$, 'nozomio-labs/nia-skill', 'nia', 0, TRUE),
        (418, 'find-animation-opportunities', $zh240$UI 动效机会发现$zh240$, $zh240$只读审查界面，指出值得增加或不应增加动画的位置，并给出具体参数和实现建议。$zh240$, $zh240$以只读方式检查 UI 与代码，识别哪些交互、状态变化和内容过渡适合加入动画，同时明确哪些地方不应动。为每个建议提供具体时长、缓动和行为参数，但不直接实现。若已有动画需要改进，请改用对应的动画审计能力。$zh240$, 'emilkowalski/skills', 'find-animation-opportunities', 0, FALSE),
        (419, 'extract', $zh240$设计系统组件与 Token 提取$zh240$, $zh240$从现有界面中识别并提取可复用组件、设计 Token 和交互模式，沉淀为设计系统。$zh240$, $zh240$分析现有界面与实现，找出重复的视觉和交互规律，将其提取为可复用组件、设计 Token 与共享模式。用于减少一次性实现、统一产品体验，并逐步建立或扩建设计系统。$zh240$, 'pbakaus/impeccable', 'extract', 0, FALSE),
        (420, 'frontend-design-anthropics-claude-code', $zh240$前端设计指导（Anthropic Claude Code）$zh240$, $zh240$以鲜明且有意图的视觉方向设计或重塑前端界面，避免模板化和泛化审美。$zh240$, $zh240$为新建或重塑的前端界面提供有辨识度、经过明确取舍的视觉设计。根据产品背景决定字体、颜色、构图、层级、动效与细节，产出可落地的高质量界面，避免千篇一律的模板感；本条目对应 Anthropic Claude Code 来源。$zh240$, 'anthropics/claude-code', 'frontend-design', 0, FALSE),
        (421, 'onboard', $zh240$新用户引导体验设计$zh240$, $zh240$设计首次使用、空状态和引导流程，让新用户更快理解产品并获得首个价值。$zh240$, $zh240$优化产品的新用户引导、首次运行体验和空状态。减少理解与操作阻力，突出下一步行动，逐步展示关键能力，使用户尽快完成有意义的任务并感受到产品价值。$zh240$, 'pbakaus/impeccable', 'onboard', 0, FALSE),
        (422, 'frontend-design-pbakaus-impeccable', $zh240$高品质前端设计（Impeccable）$zh240$, $zh240$创建富有创意且可投入生产的前端界面，以明确审美方向避免通用模板风格。$zh240$, $zh240$为网页、应用和组件创建富有创意、达到生产质量的前端界面。根据内容和品牌选择明确的设计方向，精心处理排版、布局、颜色、层级、动效与细节，避免常见的通用 AI 设计样式；本条目对应 pbakaus/impeccable 来源。$zh240$, 'pbakaus/impeccable', 'frontend-design', 0, FALSE),
        (423, 'harden', $zh240$前端界面生产级加固$zh240$, $zh240$补齐错误、空状态、引导、国际化、溢出和边界情况，使界面达到稳定的生产质量。$zh240$, $zh240$对前端界面进行生产级加固。检查并完善错误与加载状态、空状态、新手引导、国际化、长文本与内容溢出、数据缺失、权限差异和各种边界情况，确保真实环境下仍然稳定、清楚且可用。$zh240$, 'pbakaus/impeccable', 'harden', 0, FALSE),
        (424, 'opentui', $zh240$OpenTUI 终端界面开发$zh240$, $zh240$使用 OpenTUI Core、React 或 Solid 构建终端界面，涵盖组件、布局、按键、动画与测试。$zh240$, $zh240$使用 OpenTUI 构建终端用户界面，可选择 Core、React 或 Solid 绑定。涵盖组件组织、布局、键盘映射、焦点与输入、动画以及测试，适用于新建 TUI 或排查现有 OpenTUI 应用。$zh240$, 'msmps/opentui-skill', 'opentui', 0, FALSE),
        (425, 'onboarding-cro', $zh240$新用户引导转化优化$zh240$, $zh240$优化注册后的首次体验、激活和价值实现时间，改善空状态、清单、关键动作与 Aha 时刻。$zh240$, $zh240$优化注册后的用户引导、激活率、首次运行体验和价值实现时间。适用于用户完成注册却没有持续使用、设置完成率低或难以抵达 Aha 时刻的情况，可改进空状态、引导清单和首个会话。注册流程请参见 signup-flow-cro，邮件引导请参见 email-sequence。$zh240$, 'coreyhaines31/marketingskills', 'onboarding-cro', 0, FALSE),
        (426, 'ai-video-generation-skills-101-superpowers', $zh240$inference.sh AI 视频生成$zh240$, $zh240$通过 inference.sh 调用 40 多种模型完成文生视频、图生视频、参考生成、编辑、口型、数字人、放大与音效。$zh240$, $zh240$使用 inference.sh 的 40 多种视频模型进行 AI 视频创作。支持文本生成视频、图片生成视频、参考视频生成、视频编辑、口型同步、数字人、画质放大和拟音，适用于从概念到成片的多种生成与后期流程。$zh240$, 'skills-101/superpowers', 'ai-video-generation', 0, TRUE),
        (427, 'ai-image-generation-skills-101-superpowers', $zh240$inference.sh AI 图像生成$zh240$, $zh240$通过 inference.sh 调用 GPT、FLUX、Gemini、Grok、Seedream 等 50 多种模型生成、编辑、修补和放大图像。$zh240$, $zh240$使用 inference.sh 的 50 多种图像模型进行创作，包括 GPT、FLUX、Gemini、Grok 和 Seedream 等。支持文生图、图生图、局部修补、LoRA、指令编辑、画质放大以及带文字的图像生成。$zh240$, 'skills-101/superpowers', 'ai-image-generation', 0, TRUE),
        (428, 'ai-avatar-video-skills-101-superpowers', $zh240$inference.sh AI 数字人视频$zh240$, $zh240$通过 inference.sh 生成会说话的数字人与头像视频，支持 TTS、口型同步、演示讲解和 UGC 风格内容。$zh240$, $zh240$使用 inference.sh 创建 AI 数字人和会说话的头像视频。可调用 P-Video-Avatar、OmniHuman、Fabric、PixVerse 等模型，结合文字转语音和口型同步，制作主持人、演示讲解、营销与 UGC 风格视频。$zh240$, 'skills-101/superpowers', 'ai-avatar-video', 0, TRUE),
        (429, 'twitter-automation', $zh240$X（Twitter）自动化运营$zh240$, $zh240$通过 inference.sh 自动发布文字与媒体、点赞、转发、私信、关注、查询资料并安排发布时间。$zh240$, $zh240$使用 inference.sh 自动操作 X（Twitter），包括发布文字和媒体、点赞、转发、发送私信、关注账号、读取用户资料以及定时发布。适用于经授权的社交媒体运营与工作流自动化，并应遵守平台规则。$zh240$, 'skills-101/superpowers', 'twitter-automation', 0, TRUE),
        (430, 'form-cro', $zh240$表单转化率优化$zh240$, $zh240$优化线索、联系、演示申请、问卷和结账等非注册表单，降低填写阻力并提升完成率。$zh240$, $zh240$分析和优化非注册类表单的转化表现，包括线索收集、联系表单、演示申请、资格申请、问卷和结账表单。改进字段数量、顺序、文案、验证、信任与错误处理。账号注册表单请参见 signup-flow-cro。$zh240$, 'coreyhaines31/marketingskills', 'form-cro', 0, FALSE),
        (431, 'enhance-prompt', $zh240$Stitch UI 提示词增强$zh240$, $zh240$把模糊的界面想法改写为结构清晰、包含设计语汇与上下文的高质量 Stitch 提示词。$zh240$, $zh240$将简短或含糊的 UI 请求增强为适合 Stitch 的详细提示词。补充产品与用户背景、页面结构、内容层级、组件、交互、视觉风格及关键 UI/UX 术语，使生成结果更具体、更连贯且便于迭代。$zh240$, 'google-labs-code/stitch-skills', 'enhance-prompt', 0, FALSE),
        (432, 'free-tool-strategy', $zh240$免费营销工具策略$zh240$, $zh240$规划、评估和构建用于获客、SEO 与品牌认知的免费工具，如计算器、生成器、评分器和审计器。$zh240$, $zh240$制定“工程即营销”的免费工具策略，用有用的计算器、生成器、交互工具、ROI 工具、评分器或审计器吸引线索、获得外链并提升品牌认知。适用于评估是否值得构建及规划分发路径；可下载的电子书、清单和模板请参见 lead-magnets。$zh240$, 'coreyhaines31/marketingskills', 'free-tool-strategy', 0, FALSE),
        (433, 'referral-program', $zh240$推荐与联盟计划设计$zh240$, $zh240$创建、优化和分析推荐、联盟、品牌大使与口碑计划，设计激励、支付和病毒循环。$zh240$, $zh240$创建、优化或分析推荐计划、联盟计划和口碑增长策略。涵盖邀请好友、品牌大使、合作伙伴计划、推荐激励、联盟支付和病毒循环，帮助现有用户或伙伴持续带来新客户。发布期病毒传播请参见 launch-strategy。$zh240$, 'coreyhaines31/marketingskills', 'referral-program', 0, FALSE),
        (434, 'ab-test-setup', $zh240$A/B 测试与实验体系$zh240$, $zh240$规划、设计和实施 A/B 或多变量实验，并建立假设、统计、周期、优先级和实验积压体系。$zh240$, $zh240$规划、设计或实施 A/B 测试、多变量测试和增长实验。用于形成可验证假设、定义指标与样本、判断统计显著性和运行时长，并通过 ICE 等评分维护实验积压、节奏与方法手册。埋点实现请参见 analytics-tracking，页面优化请参见 page-cro。$zh240$, 'coreyhaines31/marketingskills', 'ab-test-setup', 0, FALSE),
        (435, 'signup-flow-cro', $zh240$注册流程转化优化$zh240$, $zh240$优化注册、开户和试用激活流程，减少表单摩擦、步骤过多与中途流失。$zh240$, $zh240$分析并优化注册、账号创建和试用激活流程。适用于注册转化低、表单摩擦大、步骤过多、用户中途放弃或试用开启率不足的情况。注册后的用户激活请参见 onboarding-cro，非账号类线索表单请参见 form-cro。$zh240$, 'coreyhaines31/marketingskills', 'signup-flow-cro', 0, FALSE),
        (436, 'wrangler', $zh240$Cloudflare Wrangler 开发运维$zh240$, $zh240$使用 Wrangler CLI 开发、部署和管理 Cloudflare Workers 及相关服务，并按当前官方文档配置。$zh240$, $zh240$使用 Cloudflare Wrangler CLI 开发、调试、部署和管理 Workers 及绑定的 Cloudflare 服务。涵盖项目配置、环境、密钥、资源绑定和发布流程；处理参数与行为时优先检索当前 Cloudflare 官方文档。$zh240$, 'cloudflare/skills', 'wrangler', 0, FALSE),
        (437, 'agently-mail', $zh240$Agently 邮件命令行操作$zh240$, $zh240$通过 agently-cli 发送、回复、转发、搜索和读取邮件，并下载附件与管理邮箱。$zh240$, $zh240$使用 agently-cli 操作邮件，包括发送、回复、转发、搜索、读取和下载附件，以及管理邮箱中的相关内容。适用于需要从命令行完成邮件处理和自动化的任务。$zh240$, 'agent.qq.com', 'agently-mail', 0, TRUE),
