    summary,
    description
)
SELECT
    slug,
    'zh-CN',
    display_name,
    summary,
    capability || E'\n\n' ||
        format(
            $zh240$来源说明：本条目来自 skills.sh 历史总榜第 %s 名快照；原始来源：%s；原始 slug：%s；打包时排除了 %s 个上游文件。$zh240$,
            rank,
            source,
            original_slug,
            excluded_count
        ) ||
        CASE
            WHEN license_unverified THEN
                $zh240$许可证状态：未核验；此快照未包含可核验的许可证文件，版权归原作者所有，使用与再分发前请核对来源仓库的许可证。$zh240$
            ELSE
                $zh240$许可证状态：已核验；版权归原作者所有，使用与再分发须遵循随包附带或来源仓库中的许可证。$zh240$
        END
FROM localized
ON CONFLICT (slug, locale) DO UPDATE
SET
    display_name = EXCLUDED.display_name,
    summary = EXCLUDED.summary,
    description = EXCLUDED.description,
    updated_at = NOW();
